-- Run once in Supabase Dashboard → SQL Editor. This is PostgreSQL, not MySQL.
create type user_role as enum ('ADMIN','DEPOT_MANAGER','DRIVER','CONDUCTOR','MECHANIC'); create type employee_status as enum ('ACTIVE','INACTIVE'); create type duty_shift as enum ('MORNING','AFTERNOON','NIGHT'); create type duty_status as enum ('ASSIGNED','COMPLETED','CANCELLED'); create type attendance_status as enum ('PRESENT','ABSENT','HALF_DAY'); create type leave_type as enum ('CASUAL','SICK','EARNED'); create type leave_status as enum ('PENDING','APPROVED','REJECTED'); create type bus_status as enum ('AVAILABLE','ASSIGNED','UNDER_MAINTENANCE'); create type maintenance_status as enum ('PENDING','IN_PROGRESS','COMPLETED');
create table depots(id bigint generated always as identity primary key,name varchar(120) not null,address varchar(255),created_at timestamptz default now());
create table employees(id bigint generated always as identity primary key,employee_id varchar(32) not null unique,name varchar(120) not null,email varchar(160) not null unique,phone varchar(20) not null,designation varchar(50) not null,joining_date date not null,license_number varchar(80),status employee_status not null default 'ACTIVE',depot_id bigint references depots(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table users(id bigint generated always as identity primary key,employee_id bigint not null unique references employees(id),email varchar(160) not null unique,password_hash varchar(255) not null,role user_role not null,is_active boolean not null default true,failed_login_attempts smallint not null default 0,locked_until timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table buses(id bigint generated always as identity primary key,registration_number varchar(32) not null unique,model varchar(100) not null,seating_capacity smallint not null check(seating_capacity>0),fuel_type varchar(30) not null,status bus_status not null default 'AVAILABLE',depot_id bigint references depots(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table routes(id bigint generated always as identity primary key,route_code varchar(32) not null unique,route_name varchar(150) not null,start_point varchar(100) not null,end_point varchar(100) not null,stops jsonb default '[]'::jsonb,depot_id bigint references depots(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table maintenance(id bigint generated always as identity primary key,bus_id bigint not null references buses(id),maintenance_type varchar(100) not null,due_date date not null,status maintenance_status not null default 'PENDING',parts_used text,cost numeric(12,2) not null default 0,remarks text,created_at timestamptz default now(),updated_at timestamptz default now());
create table duties(id bigint generated always as identity primary key,employee_id bigint not null references employees(id),bus_id bigint not null references buses(id),route_id bigint not null references routes(id),duty_date date not null,shift duty_shift not null,start_time time not null,end_time time not null,status duty_status not null default 'ASSIGNED',created_by bigint not null references users(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table attendance(id bigint generated always as identity primary key,employee_id bigint not null references employees(id),duty_id bigint not null references duties(id),attendance_date date not null,status attendance_status not null,marked_at timestamptz default now(),check_out_at timestamptz,unique(employee_id,attendance_date));
create table leaves(id bigint generated always as identity primary key,employee_id bigint not null references employees(id),leave_type leave_type not null,start_date date not null,end_date date not null check(end_date>=start_date),reason text not null,status leave_status not null default 'PENDING',approved_by bigint references users(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table leave_balances(employee_id bigint primary key references employees(id),casual_days numeric(4,1) not null default 12,sick_days numeric(4,1) not null default 10,earned_days numeric(4,1) not null default 15,updated_at timestamptz default now());
create table notifications(id bigint generated always as identity primary key,user_id bigint not null references users(id),type varchar(40) not null,title varchar(160) not null,message text not null,is_read boolean not null default false,created_at timestamptz default now()); create table reports(id bigint generated always as identity primary key,report_type varchar(40) not null,generated_by bigint not null references users(id),filters jsonb,created_at timestamptz default now()); create table audit_logs(id bigint generated always as identity primary key,user_id bigint references users(id) on delete set null,action varchar(80) not null,description text not null,created_at timestamptz default now());
create index idx_duty_employee_date on duties(employee_id,duty_date); create index idx_duty_bus_date on duties(bus_id,duty_date); create index idx_leave_employee_date on leaves(employee_id,start_date,end_date,status); create index idx_maintenance_bus_status on maintenance(bus_id,status); create index idx_notification_user_read on notifications(user_id,is_read);
